def tail(t,df,n=32768):
    # Positive survival integral, x=1/u. Avoid 1-CDF cancellation at tiny p.
    assert t>0 and df>1
    logc=math.lgamma((df+1)/2)-math.lgamma(df/2)-.5*math.log(df*math.pi);end=1/t;h=end/n
    def f(u):return 0. if u==0 else math.exp(logc-(df+1)/2*math.log1p(1/(u*u*df))-2*math.log(u))
    return h/3*(f(end)+sum((4 if j%2 else 2)*f(j*h) for j in range(1,n)))
